[ExtensionOf(classStr(PurchPurchaseOrderDP))]
final class KpmgPurchPurchaseOrderDP_Extension
{
}

Method.Source:
/// <summary>
/// Insert the order header.
/// </summary>
/// <param name = "_purchaseOrderHeader">
/// A <c>PurchPurchaseOrderHeader</c> record to insert.
/// </param>
protected void insertOrderHeader(PurchPurchaseOrderHeader _purchaseOrderHeader)
{
    PurchTable purchTable                      = PurchTable::find(_purchaseOrderHeader.PurchId);
    _purchaseOrderHeader.Payment               = PaymTerm::find(purchTable.Payment).Description;        
    _purchaseOrderHeader.KPMGContactPersonId   = purchTable.contactPersonName();
    _purchaseOrderHeader.KPMGPurchOrderFormNum = purchTable.PurchOrderFormNum;
    next insertOrderHeader(_purchaseOrderHeader);
}

    /// <summary>
    /// Initializes the purchase order header.
    /// </summary>
    /// <param name = "_vendPurchOrderJour">
    /// A <c>VendPurchOrderJour</c> purchase order journal header which the order header is initialized from.
    /// </param>
    /// <returns>
    /// The initialized <c>PurchPurchaseOrderHeader</c> record.
    /// </returns>
    protected PurchPurchaseOrderHeader initializePurchaseOrderHeader(VendPurchOrderJour _vendPurchOrderJour)
    {
        PurchPurchaseOrderHeader    KPMGPurchPurchaseOrderHeader;

        KPMGPurchPurchaseOrderHeader = next initializePurchaseOrderHeader(_vendPurchOrderJour);

        KPMGPurchPurchaseOrderHeader.SalesOrderBalance          = _vendPurchOrderJour.SalesOrderbalance;
        KPMGPurchPurchaseOrderHeader.EndDisc                    = _vendPurchOrderJour.EndDisc;
        KPMGPurchPurchaseOrderHeader.SumMarkup                  = _vendPurchOrderJour.SumMarkup;
        KPMGPurchPurchaseOrderHeader.SumTax                     = _vendPurchOrderJour.SumTax;
        KPMGPurchPurchaseOrderHeader.RoundOff                   = _vendPurchOrderJour.RoundOff;
        KPMGPurchPurchaseOrderHeader.Amount                     = _vendPurchOrderJour.Amount;

        return KPMGPurchPurchaseOrderHeader;
    }
